<?php
header('Cache-Control: no-store, private');header('X-Content-Type-Options: nosniff');
function qcFail($status,$message){http_response_code($status);header('Content-Type: application/json; charset=utf-8');echo json_encode(['error'=>$message],JSON_UNESCAPED_UNICODE);exit;}
try{
 session_start();if(empty($_SESSION['user'])||(isset($_SESSION['expire'])&&$_SESSION['expire']<time()))qcFail(401,'Inicia sesión nuevamente.');
 require_once dirname(__DIR__).'/config/database.php';require_once __DIR__.'/ali-pos-security.php';require_once __DIR__.'/proforma-contract-core.php';require_once __DIR__.'/proforma-contract-numbering.php';
 $db=appPdoConnection();$db->setAttribute(PDO::ATTR_ERRMODE,PDO::ERRMODE_EXCEPTION);$user=(string)$_SESSION['user'];$access=aliPosCapabilities($db,$user);if(empty($access['read']))qcFail(403,'No tienes acceso a las propuestas.');
 if(empty($_SESSION['proforma_contract_csrf']))$_SESSION['proforma_contract_csrf']=bin2hex(random_bytes(24));$csrf=$_SESSION['proforma_contract_csrf'];
 $method=$_SERVER['REQUEST_METHOD'];if(!in_array($method,['GET','POST'],true))qcFail(405,'Método no permitido.');
 if($method==='POST'){if(empty($access['write']))qcFail(403,'No tienes permiso para generar contratos.');if(!hash_equals($csrf,$_SERVER['HTTP_X_CONTRACT_CSRF']??''))qcFail(403,'Vuelve a abrir el contrato e intenta nuevamente.');}
 session_write_close();
 if($method==='GET'&&isset($_GET['contrato'])){
  $cid=filter_var($_GET['contrato'],FILTER_VALIDATE_INT);if(!$cid||$cid<1)qcFail(422,'Contrato inválido.');$s=$db->prepare('SELECT Datos FROM Ve_ProformaContrato WHERE IdContrato=?');$s->execute([$cid]);$raw=$s->fetchColumn();if(!$raw)qcFail(404,'Contrato no disponible.');$data=json_decode($raw,true);$html=qcHtml($data);
  if(isset($_GET['html'])){header('Content-Type: text/html; charset=utf-8');header("Content-Security-Policy: default-src 'none'; img-src data:; style-src 'unsafe-inline'; base-uri 'none'; form-action 'none'");echo $html;exit;}
  require_once __DIR__.'/sunat/plugins/dompdf/lib/php-font-lib/src/FontLib/Autoloader.php';require_once __DIR__.'/sunat/plugins/dompdf/lib/php-svg-lib/src/autoload.php';require_once __DIR__.'/sunat/plugins/dompdf/src/Autoloader.php';Dompdf\Autoloader::register();$options=new Dompdf\Options();$options->set('isRemoteEnabled',false);$options->set('isPhpEnabled',false);$pdf=new Dompdf\Dompdf($options);$pdf->setPaper('A4');$pdf->loadHtml($html,'UTF-8');$pdf->render();if(($data['templateVersion']??1)>=2)qcPdfNumberPages($pdf);$bytes=$pdf->output();header('Content-Type: application/pdf');header('Content-Disposition: '.(isset($_GET['descargar'])?'attachment':'inline').'; filename="contrato-sistemas-'.(int)$cid.'.pdf"');header('Content-Length: '.strlen($bytes));echo $bytes;exit;
 }
 if($method==='POST'){if((int)($_SERVER['CONTENT_LENGTH']??0)>100000)qcFail(413,'Los datos del contrato son demasiado extensos.');$body=json_decode(file_get_contents('php://input'),true);if(!is_array($body))qcFail(422,'Revisa los datos del contrato.');$id=filter_var($body['IdProforma']??0,FILTER_VALIDATE_INT);}else{$id=filter_var($_GET['id']??0,FILTER_VALIDATE_INT);}
 if(!$id||$id<1)qcFail(422,'Selecciona una proforma válida.');
 if($method==='GET'){$source=qcSource($db,$id);$year=filter_var($_GET['anio']??(new DateTimeImmutable('now',new DateTimeZone('America/Lima')))->format('Y'),FILTER_VALIDATE_INT);if(!$year||$year<1900||$year>2100)qcFail(422,'Revisa el año del contrato.');$numberInfo=qcSequenceInfo($db,$id,$year);$s=$db->prepare('SELECT IdContrato,Version,Datos,SourceHash,Fecha FROM Ve_ProformaContrato WHERE IdProforma=? ORDER BY Version DESC LIMIT 1');$s->execute([$id]);$latest=$s->fetch(PDO::FETCH_ASSOC);$saved=$latest?json_decode($latest['Datos'],true):null;header('Content-Type: application/json; charset=utf-8');echo json_encode(['csrf'=>$csrf,'sourceHash'=>qcHash($source),'total'=>qcTotal($source['products'])/100,'numeroContrato'=>$numberInfo['numeroContrato'],'numeroAsignado'=>$numberInfo['numeroAsignado'],'cliente'=>['nombre'=>$source['quote']['Cliente'],'documento'=>$source['quote']['Documento'],'direccion'=>$source['quote']['ClienteDireccion']],'contract'=>$latest?['id'=>(int)$latest['IdContrato'],'version'=>(int)$latest['Version'],'form'=>$saved['form'],'stale'=>!hash_equals($latest['SourceHash'],qcHash($source)),'url'=>'/api/proforma-contract.php?contrato='.(int)$latest['IdContrato']]:null],JSON_UNESCAPED_UNICODE|JSON_INVALID_UTF8_SUBSTITUTE);exit;}
 $db->beginTransaction();$s=$db->prepare('SELECT IdProforma FROM Ve_Proforma WHERE IdProforma=? FOR UPDATE');$s->execute([$id]);$source=qcSource($db,$id);if(!is_string($body['sourceHash']??null)||!hash_equals(qcHash($source),$body['sourceHash'])){$db->rollBack();qcFail(409,'La proforma cambió. Vuelve a abrir el contrato para revisar los nuevos términos e importes.');}
 $input=qcInput($body,$source);$input['numeroContrato']=qcAssignNumber($db,$id,(int)substr($input['fecha'],0,4));$saved=qcSaveDraft($db,$id,$source,$input,$user);$db->commit();header('Content-Type: application/json; charset=utf-8');echo json_encode(['id'=>$saved['id'],'version'=>$saved['version'],'numeroContrato'=>$input['numeroContrato'],'url'=>'/api/proforma-contract.php?contrato='.$saved['id'],'totals'=>['total'=>$input['totalCentimos']/100,'adelanto'=>$input['adelantoCentimos']/100,'saldo'=>$input['saldoCentimos']/100]],JSON_UNESCAPED_UNICODE);
}catch(InvalidArgumentException $e){if(isset($db)&&$db->inTransaction())$db->rollBack();qcFail(422,$e->getMessage());}catch(Throwable $e){if(isset($db)&&$db->inTransaction())$db->rollBack();error_log('Quote contract: '.$e->getMessage());qcFail(500,'No se pudo preparar el contrato. Tus datos se conservan en pantalla.');}
